#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

static void print_usage(void) {
    puts("USAGE");
}

static int normalise_shift(long v) {
    int s = (int)(v % 26);
    if (s < 0) s += 26;
    return s;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        print_usage();
        return 0;
    }
    char *endptr = NULL;
    long raw_shift = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        print_usage();
        return 0;
    }
    int shift = normalise_shift(raw_shift);
    const char *text = argv[2];
    size_t len = strlen(text);
    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)text[i];
        if (isupper(c)) {
            putchar(((c - 'A' + shift) % 26) + 'A');
        } else if (islower(c)) {
            putchar(((c - 'a' + shift) % 26) + 'a');
        } else {
            putchar(c);
        }
    }
    putchar('\n');
    return 0;
}
